questions.question_text:
The continuous random variable $X$ has cumulative distribution function $F(x)=\frac{x^{2}}{36}$ on $[0,6]$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$F(x)$}, xmin=-0.8, xmax=7.2, ymin=-0.18, ymax=1.25, samples=100, clip=false, width=8cm, height=6cm, xtick={0,1,2,3,4,5,6}, ytick={0.25,0.5,0.75,1}]
\addplot[thick, domain=0:6] {x*x/36};
\end{axis}
\end{tikzpicture}
[/tikz]
Find the median, correct to two decimal places.

questions.solution_text:
$\frac{m^{2}}{36}=0.5$
$m^{2}=18$
$m=\sqrt{18}$
$\approx 4.24$
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$F(x)$}, xmin=-0.8, xmax=7.2, ymin=-0.18, ymax=1.25, samples=100, clip=false, width=8cm, height=6cm, xtick={0,1,2,3,4,5,6}, ytick={0.25,0.5,0.75,1}]
\addplot[thick, domain=0:6] {x*x/36};
\draw[dashed] (axis cs:0,0.5) -- (axis cs:4.2426,0.5) -- (axis cs:4.2426,0);
\node[right] at (axis cs:4.4,0.3) {$m\approx 4.24$};
\end{axis}
\end{tikzpicture}
[/tikz]

questions.question_text:
The continuous random variable $X$ has cumulative distribution function $F(x)=\frac{x^{3}}{27}$ on $[0,3]$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$F(x)$}, xmin=-0.5, xmax=4.2, ymin=-0.18, ymax=1.25, samples=100, clip=false, width=8cm, height=6cm, xtick={0,1,2,3}, ytick={0.25,0.5,0.75,1}]
\addplot[thick, domain=0:3] {x*x*x/27};
\end{axis}
\end{tikzpicture}
[/tikz]
