\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$F(x)$}, xmin=-0.5, xmax=4.2, ymin=-0.18, ymax=1.25, samples=100, clip=false, width=8cm, height=6cm, xtick={0,1,2,3}, ytick={0.25,0.5,0.75,1}]
\addplot[thick, domain=0:3] {x*x*x/27};
\draw[dashed] (axis cs:0,0.25) -- (axis cs:1.8899,0.25) -- (axis cs:1.8899,0);
\node[right] at (axis cs:2.05,0.13) {$Q_{1}\approx 1.89$};
\end{axis}
\end{tikzpicture}
[/tikz]

questions.question_text:
The continuous random variable $X$ has probability density function $f(x)=\frac{x}{50}$ on $[0,10]$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$}, xmin=-1.2, xmax=11.6, ymin=-0.04, ymax=0.28, samples=100, clip=false, width=8cm, height=6cm, xtick={0,2,4,6,8,10}, ytick={0.05,0.1,0.15,0.2}]
\addplot[thick, domain=0:10] {x/50};
\end{axis}
\end{tikzpicture}
[/tikz]
Find the median, correct to two decimal places.

questions.solution_text:
$F(x)=\int_{0}^{x}\frac{t}{50}\,dt$
$=\frac{x^{2}}{100}$
$\frac{m^{2}}{100}=0.5$
$m^{2}=50$
$m=\sqrt{50}$
$\approx 7.07$
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$}, xmin=-1.2, xmax=11.6, ymin=-0.04, ymax=0.28, samples=100, clip=false, width=8cm, height=6cm, xtick={0,2,4,6,8,10}, ytick={0.05,0.1,0.15,0.2}]
\addplot[draw=none, fill=gray!35, domain=0:7.0711] {x/50} \closedcycle;
\addplot[thick, domain=0:10] {x/50};
\draw[dashed] (axis cs:7.0711,0) -- (axis cs:7.0711,0.1414);
\node[above left] at (axis cs:7.0711,0.16) {$m\approx 7.07$};
\end{axis}
\end{tikzpicture}
[/tikz]

questions.question_text:
The continuous random variable $X$ has probability density function $f(x)=\frac{2(5-x)}{25}$ on $[0,5]$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$}, xmin=-0.7, xmax=6.2, ymin=-0.06, ymax=0.55, samples=100, clip=false, width=8cm, height=6cm, xtick={0,1,2,3,4,5}, ytick={0.1,0.2,0.3,0.4}]
\addplot[thick, domain=0:5] {2*(5-x)/25};
\end{axis}
\end{tikzpicture}
[/tikz]
Find the median, correct to two decimal places.

questions.solution_text:
$F(x)=\int_{0}^{x}\frac{2(5-t)}{25}\,dt$
$=\frac{2}{25}\left[5t-\frac{t^{2}}{2}\right]_{0}^{x}$
$=\frac{10x-x^{2}}{25}$
$\frac{10m-m^{2}}{25}=0.5$
$m^{2}-10m+12.5=0$
$m=\frac{10\pm\sqrt{100-50}}{2}$
$m\approx 1.46$ or $m\approx 8.54$
The root $m\approx 8.54$ is rejected because it lies outside $[0,5]$.
$m\approx 1.46$
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$}, xmin=-0.7, xmax=6.2, ymin=-0.06, ymax=0.55, samples=100, clip=false, width=8cm, height=6cm, xtick={0,1,2,3,4,5}, ytick={0.1,0.2,0.3,0.4}]
\addplot[draw=none, fill=gray!35, domain=0:1.4645] {2*(5-x)/25} \closedcycle;
\addplot[thick, domain=0:5] {2*(5-x)/25};
\draw[dashed] (axis cs:1.4645,0) -- (axis cs:1.4645,0.2828);
\node[above right] at (axis cs:1.4645,0.31) {$m\approx 1.46$};
\end{axis}
\end{tikzpicture}
[/tikz]

questions.question_text:
The continuous random variable $X$ has cumulative distribution function $F(x)=\frac{x^{2}-4}{32}$ on $[2,6]$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$F(x)$}, xmin=-0.5, xmax=7.4, ymin=-0.18, ymax=1.25, samples=100, clip=false, width=8cm, height=6cm, xtick={0,2,4,6}, ytick={0.25,0.5,0.75,1}]
\addplot[thick, domain=2:6] {(x*x-4)/32};
\end{axis}
\end{tikzpicture}
[/tikz]
Find the $30$th percentile, correct to two decimal places.

questions.solution_text:
$\frac{x^{2}-4}{32}=0.3$
$x^{2}-4=9.6$
$x^{2}=13.6$
$x=\sqrt{13.6}$
$\approx 3.69$
The root $x=-\sqrt{13.6}$ is rejected because it lies outside $[2,6]$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$F(x)$}, xmin=-0.5, xmax=7.4, ymin=-0.18, ymax=1.25, samples=100, clip=false, width=8cm, height=6cm, xtick={0,2,4,6}, ytick={0.25,0.5,0.75,1}]
\addplot[thick, domain=2:6] {(x*x-4)/32};
\draw[dashed] (axis cs:2,0.3) -- (axis cs:3.6878,0.3) -- (axis cs:3.6878,0);
\node[right] at (axis cs:3.85,0.16) {$x\approx 3.69$};
\end{axis}
\end{tikzpicture}
[/tikz]

questions.question_text:
The continuous random variable $X$ has cumulative distribution function $F(x)=\frac{x^{4}}{16}$ on $[0,2]$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$F(x)$}, xmin=-0.4, xmax=3.2, ymin=-0.18, ymax=1.25, samples=100, clip=false, width=8cm, height=6cm, xtick={0,1,2}, ytick={0.25,0.5,0.75,1}]
\addplot[thick, domain=0:2] {x*x*x*x/16};
\end{axis}
\end{tikzpicture}
[/tikz]
Find the interquartile range, correct to two decimal places.

questions.solution_text:
$\frac{x^{4}}{16}=0.25$
$x^{4}=4$
$Q_{1}=\sqrt{2}$
$\approx 1.4142$
$\frac{x^{4}}{16}=0.75$
$x^{4}=12$
$Q_{3}=\sqrt[4]{12}$
$\approx 1.8612$
$\text{IQR}=1.8612-1.4142$
$\approx 0.45$
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$F(x)$}, xmin=-0.4, xmax=3.2, ymin=-0.18, ymax=1.25, samples=100, clip=false, width=8cm, height=6cm, xtick={0,1,2}, ytick={0.25,0.5,0.75,1}]
\addplot[thick, domain=0:2] {x*x*x*x/16};
\draw[dashed] (axis cs:0,0.25) -- (axis cs:1.4142,0.25) -- (axis cs:1.4142,0);
\draw[dashed] (axis cs:0,0.75) -- (axis cs:1.8612,0.75) -- (axis cs:1.8612,0);
\node[right] at (axis cs:1.5,0.1) {$Q_{1}$};
\node[right] at (axis cs:1.95,0.6) {$Q_{3}$};
\end{axis}
\end{tikzpicture}
[/tikz]

questions.question_text:
The time $X$ hours until a sensor first reports a fault has probability density function $f(x)=\frac{3(2-x)^{2}}{8}$ on $[0,2]$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$}, xmin=-0.4, xmax=3.2, ymin=-0.22, ymax=1.9, samples=100, clip=false, width=8cm, height=6cm, xtick={0,1,2}, ytick={0.5,1,1.5}]
\addplot[thick, domain=0:2] {3*(2-x)*(2-x)/8};
\end{axis}
\end{tikzpicture}
[/tikz]
Find the median time, correct to two decimal places.

questions.solution_text:
$F(x)=\int_{0}^{x}\frac{3(2-t)^{2}}{8}\,dt$
$=\left[-\frac{(2-t)^{3}}{8}\right]_{0}^{x}$
$=1-\frac{(2-x)^{3}}{8}$
$1-\frac{(2-m)^{3}}{8}=0.5$
$(2-m)^{3}=4$
$2-m=\sqrt[3]{4}$
$2-m\approx 1.5874$
$m\approx 0.41$
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$}, xmin=-0.4, xmax=3.2, ymin=-0.22, ymax=1.9, samples=100, clip=false, width=8cm, height=6cm, xtick={0,1,2}, ytick={0.5,1,1.5}]
\addplot[draw=none, fill=gray!35, domain=0:0.4126] {3*(2-x)*(2-x)/8} \closedcycle;
\addplot[thick, domain=0:2] {3*(2-x)*(2-x)/8};
\draw[dashed] (axis cs:0.4126,0) -- (axis cs:0.4126,0.9449);
\node[above right] at (axis cs:0.4126,1.0) {$m\approx 0.41$};
\end{axis}
\end{tikzpicture}
[/tikz]

