\addplot[thick, domain=0:8] {x/32};
\draw[dashed] (axis cs:4,0) -- (axis cs:4,0.125);
\node[above left] at (axis cs:4,0.15) {$Q_{1}=4$};
\end{axis}
\end{tikzpicture}
[/tikz]
